def left_Rotate(n, d):
    # Check if the number of rotations is less than the number of bits of n
    if d < len(bin(n)[2:]):
        # Perform left rotation by shifting the bits
        rotation = n << d
        return rotation
    else:
        # If rotations exceed the number of bits, perform modulo operation first
        return n << (d % len(bin(n)[2:]))
