def Sum_of_Inverse_Divisors(x, y):
    counter = 1
    result = 0
    while counter * counter <= x and counter * counter <= y:
        if x % counter == 0 and y % counter == 0:
            result = result + (1/counter) + (1/y/counter)
        counter += 1
    return result
