import math

def compute_sum(inverse_list):
    total_sum = 0
    for num in inverse_list:
        total_sum += 1 / num
    return total_sum

def Sum_of_Inverse_Divisors(n, t):
    inverse_list = [math.inv(i) for i in range(n, 1, -1)]
    return round(compute_sum(inverse_list) * t, 6)
