        return 0

    n = len(arr)
    # dp array for increasing bitsonic subsequence of length 1
    dp1 = [1] * n
    # dp array for decreasing bitsonic subsequence of length 1
    dp2 = [1] * n

    for i in range(1, n):
        # Find length of increasing bitsonic subsequence ending at i
        for j in range(i):
            if arr[i] > arr[j] and dp1[i] < dp1[j] + 1:
                dp1[i] = dp1[j] + 1

        # Find length of decreasing bitsonic subsequence starting at i
        for j in range(i):
            if arr[i] < arr[j] and dp2[i] < dp2[j] + 1:
                dp2[i] = dp2[j] + 1

    # The length of the longest bitonic subsequence is the maximum of
    # all dp1[i] and dp2[i] for i in range(n)
    return max([dp1[i] + dp2[i] - 1 for i in range(n)])
