def dealnnoy_num(n, k):  
    # Initialize the first two values of the delannoy triangle
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        # Use dynamic programming to build up the delannoy triangle row by row
        row = [1] * (k + 1)
        for i in range(1, n):
            for j in range(k + 1):
                if j == 0 or j == i:
                    row[j] = 1
                else:
                    row[j] = row[j] + row[j - 1]
        return row[-1]
