def max_sub_array_sum(arr, k):
    # dictionary to cache the sums of subarrays of size k
    subarr_sum_cache = {}
    current_sum = 0
    max_sum = 0
    # iterate through the array
    for i in range(len(arr)):
        current_sum += arr[i]  # update the current sum
        if i >= k:
            current_sum -= arr[i - k]  # subtract the oldest sum from the current sum
        # if current sum is maximum, update max_sum
        if i >= k - 1 and current_sum > max_sum:
            max_sum = current_sum
        # if current_sum is not in the cache, add it
        if current_sum not in subarr_sum_cache:
            subarr_sum_cache[current_sum] = i
    return max_sum
