import heapq

def nth_super_ugly_number(n, primes):
    # Initialize a set to store the available ugly numbers
    seen = set([1]);
    # Initialize a min heap with the first ugly number
    pq = [1];
    numb = 1;

    # Iterate n-1 times to find the nth ugly number
    for _ in range(1, n):
        smallest = heapq.heappop(pq);  # Get the smallest number from the heap
        numb = smallest;  # Update the current ugly number

        # Check each prime number in the primes array
        for prime in primes:
            # If adding the current prime to the number results in a new ugly number
            if smallest * prime not in seen:
                # Push the new ugly number into the min heap and add it to the set
                heapq.heappush(pq, smallest * prime);
                seen.add(smallest * prime);

    # Return the nth ugly number
    return numb
```

