import heapq

def nth_super_ugly_number(n, primes):
    heap = [0] * k
    for i in range(k):
        heap[i] = primes[i]
    heapq.heapify(heap)
    uglies = {0}
    while len(uglies) < n:
        ugly = heapq.heappop(heap)
        for j in range(k):
            if ugly == heap[j]:
                heapq.heappush(heap, primes[j] * ugly)
        uglies.add(ugly)
    return sorted(uglies)[n-1]
