def unique_sublists(lst):
    # Use a dictionary to count occurrences of each list
    count_dict = collections.defaultdict(int)
    for sublist in lst:
        count_dict[tuple(sublist)] += 1
    # Filter out lists that occur more than once to get unique lists
    unique_lists = {k: v for k, v in count_dict.items() if v == 1}
    # Convert the dictionary back to a dictionary of tuples for the final output
    return dict(unique_lists)
