def coin_change(coins, amount, n):
    # Base case: if amount is reduced to zero, there's one way to do it
    if amount == 0:
        return 1
    # If amount is negative, it's impossible to make that amount
    elif amount < 0:
        return 0
    # If no coins are left, it's impossible to make the amount
    elif n == 0:
        return 0
    # Total number of ways = ways to make the amount with n-1 coins + ways to make the amount without n-1 coins
    return coin_change(coins, amount - coins[n-1], n) + coin_change(coins, amount, n-1)
