    # iteratively find and return the smallest of the remaining values
    lower = max(lower_bound, new_lower_bound)
    upper = min(upper_bound, new_upper_bound)
    while lower < upper-1:
        mid = (lower + upper) // 2
        if lower == mid: break
        elif mid < upper - 1:
            lower = mid
        else:
            upper = mid - 1
    return (lower, upper)
