        # For each element starting from the next element
        for j in range(i + 1, size):
            # For each element starting from the element after the second element
            for k in range(j + 1, size):
                # Check if the sum of the three elements equals the given value
                if arr[i] + arr[j] + arr[k] == value:
                    return (arr[i], arr[j], arr[k]) # Return the triplet
