    dp = [0] * n  # Initialize a DP array with zeros, each entry corresponding to a subset size
    dp[0] = 1  # There's always at least one subset of size 1 for each element

    # Fill the dp array where dp[i] represents the maximum subset size that includes arr[i]
    for i in range(1, n):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The largest subset size will be the maximum value in the dp array
    return max(dp)
