def max_chain_length(pairs, n):
    pairs.sort(key=lambda x: x.first)  # Sort pairs based on their first element
    dp = [1] * n  # Initialize DP array with 1s
    mxlen = 1  # Initialize maximum length to 1 (pair itself)

    for i in range(1, n):
        for j in range(i):
            if pairs[i].first > pairs[j].second:
                dp[i] = max(dp[i], dp[j] + 1)
                mxlen = max(mxlen, dp[i])
    return mxlen
