class Pair:
    def __init__(self, start, end):
        self.start = start
        self.end = end

class Node:
    def __init__(self, pair):
        self.pair = pair
        self.children = {}

def build_tree(pairs):
    tree = {}
    for pair in pairs:
        if pair.start not in tree:
            tree[pair.start] = Node(pair)
        if pair.end not in tree:
            tree[pair.end] = Node(pair)
        tree[pair.start].children[pair.end] = 1

def max_chain_length(pairs, n):
    max_length = 0
    max_chain = set()
    build_tree(pairs)

    def create_chain(node, path):
        nonlocal max_length, max_chain
        path.add(node.pair.start)
        if max_length < len(path):
            max_length = len(path)
            max_chain = path.copy()
        for end in node.children:
            path.add(end)
            create_chain(tree[end], path)
            path.remove(end)

    create_chain(tree[pairs[0].start], set())
    return max_length
```

