class Pair:
    def __init__(self, first, second):
        self.first = first
        self.second = second

def max_chain_length(pairs, n):
    dp = [1] * n  # Each element of dp is initialized to 1 for the base case

    # Sort the pairs based on the first element of each pair
    pairs = sorted(pairs, key=lambda p: p.first)

    for i in range(1, n):
        for j in range(i):
            if pairs[i].first > pairs[j].second:  # If the first element of current pair is greater than the second element of previous pair
                dp[i] = max(dp[i], dp[j] + 1)  # Update dp[i] if the condition is met

    max_chain_length = max(dp)  # Return the maximum value in dp
    return max_chain_length
```

