    Repeated_roots = False

    # Calculating the discriminant
    discriminant = (b**2) - (4*a*c)

    if discriminant == 0:
        Roots_sum = -(b / a)
        Roots_product = (c / a)
        if Roots_sum == 1 or Roots_product == 1:
            Repeated_roots = True
    elif discriminant > 0:
        Roots_sum = -(b / a)
        Roots_product = (c / a)
        if Roots_sum == 1 or Roots_product == 1:
            Repeated_roots = True
    else:
        Repeated_roots = False
    return "Yes" if Repeated_roots else "No"
