def max_sum_subseq(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]
    if len(arr) == 2:
        return max(arr[0], arr[1])

    dp = [0] * (len(arr) + 1)
    dp[1] = arr[0]
    dp[2] = max(arr[0], arr[1])

    for i in range(3, len(arr) + 1):
        dp[i] = max(dp[i-1], arr[i-1] + dp[i-3])

    return dp[len(arr)]
