```python
def max_sum_subseq(arr):
    # Base cases
    if len(arr) == 1:
        return arr[0]
    if len(arr) == 2:
        return max(arr[0], arr[1])

    # Dynamic programming array to store maximum sum considering or not considering the current element
    dp = [0] * len(arr)
    dp[0] = arr[0]
    dp[1] = max(arr[0], arr[1])

    for i in range(2, len(arr)):
        dp[i] = max(arr[i] + dp[i - 2], dp[i - 1])

    # The maximum sum will be at the end of the dp array
    return dp[-1]
```

