def count_Fac(num):
    # Dictionary to count powers of prime factors
    prime_factors = {}

    # Divide num by 2 until it is no longer even
    while num % 2 == 0:
        prime_factors[2] = prime_factors.get(2, 0) + 1
        num //= 2

    # Divide num by odd numbers starting from 3
    for i in range(3, int(num**0.5) + 1, 2):
        while num % i == 0:
            prime_factors[i] = prime_factors.get(i, 0) + 1
            num //= i

    # If num is a prime number greater than 2
    if num > 2:
        prime_factors[num] = prime_factors.get(num, 0) + 1

    # Return the count of distinct prime factors
    return len(prime_factors)
```

