def increment_numerics(string_list, k):
    result = []
    for string in string_list:
        incremented_string = ""
        for char in string:
            if char.isdigit():
                # Convert digit character to integer, add k, and convert back to character
                incremented_char = str(int(char) + k)
                incremented_string += incremented_char
            else:
                # If the character is not a digit, add it as is
                incremented_string += char
        result.append(incremented_string)
    return result
