def find_longest_conseq_subseq(nums, n):
    # Initialize the list to store the length of longest consecutive subsequence ending with each element
    arr = [1] * n
    # Iterate through the list starting from the second element
    for i in range(1, n):
        # If the current element is 1 more than the previous element, update the length
        if nums[i] == nums[i-1] + 1:
            arr[i] = arr[i-1] + 1
    # The maximum value in the array represents the length of the longest consecutive subsequence
    return max(arr)
```

```python
def find_longest_conseq_subseq(nums, n):
    if n == 1:
        return n

    # Initialize an array to store counts of consecutive subsequences
    dp = [1] * n

    # Build the dp array
    for i in range(1, n):
        for j in range(i):
            if nums[i] - nums[j] == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # Return the maximum value in dp array, which represents the longest consecutive subsequence
    return max(dp)
```

