```python
def lobb_num(m, n):
    if m == n == 1:
        return 1
    elif m < n or n == 0:
        return 0
    else:
        # Use dynamic programming to compute the Lobb number
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = 1
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if i >= j:
                    dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1]
                else:
                    dp[i][j] = dp[i - 1][j]
        return dp[m][n]
```

