        return None  # Not enough elements to form a pair

    # Find the maximum and minimum elements
    max1, max2 = max(arr), min(arr)
    min1, min2 = min(arr), max(arr)

    # Check if the maximum elements are equal
    if max1 == max2:
        return (max1, max1)

    # Check if the minimum elements are equal
    if min1 == min2:
        return (min1, min1)

    # The pair with the highest product
    if (max1 * max2) > (min1 * min2):
        return (max1, max2)
    else:
        return (min1, min2)
