            start = find_kth(arr1[k1-k2:], arr2, 1, k2, k)
        elif k2 > k1:
            start = find_kth(arr1, arr2[k2-k1:], k1, 1, k)
    else:
        raise ValueError("k must be within the bounds of the arrays.")
    return start
```

