def find_kth(arr1, arr2, start1, end1, start2, end2, k):
    while start1 <= end1 and start2 <= end2:
        if k == 1:
            return min(arr1[start1], arr2[start2])
        mid1 = (start1 + end1) // 2
        mid2 = (start2 + end2) // 2
        if mid1 + mid2 < k:
            k -= mid1 + mid2
            if mid1 < end1:
                start1 = mid1 + 1
            if mid2 < end2:
                start2 = mid2 + 1
        else:
            end2 = mid2 - 1
    return arr1[start1] if start1 <= end1 else arr2[start2]
```

