def extract_elements(arr, n):
    # Check if the list is empty or the number of elements to extract is too large
    if not arr or n > len(arr):
        return []

    # Traverse the list twice to extract elements that follow each other
    result = []
    for i in range(0, len(arr) - n + 1):
        for j in range(i, i + n):
            result.append(arr[j])
            break

    return result
