def maxAverageOfPath(matrix, n):
    def is_safe(y, x):
        return 0 <= y < n and 0 <= x < n and matrix[y][x] != -1

    def dfs(y, x, tracker, path_avg, max_avg):
        if len(tracker) == n and path_avg > max_avg:
            max_avg = path_avg
        elif len(tracker) == n:
            return

        path_avg += matrix[y][x]
        tracker.append(matrix[y][x])

        for dy, dx in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            ny, nx = y + dy, x + dx
            if is_safe(ny, nx):
                dfs(ny, nx, tracker, path_avg, max_avg)

        path_avg -= matrix[y][x]
        tracker.pop()

    max_avg = float('-inf')
    for y in range(n):
        for x in range(n):
            if matrix[y][x] != -1:
                path_avg = matrix[y][x]
                dfs(y, x, [matrix[y][x]], path_avg, max_avg)

    return max_avg / n
```

