import re

def find_adverbs(sentence):
    adverb_pattern = r'\b[A-Z][a-z]+[aeiou]?ly\b'
    adverbs = [match.group(0) for match in re.finditer(adverb_pattern, sentence)]
    positions = [(match.start(), match.end()) for match in re.finditer(adverb_pattern, sentence)]

    if adverbs:
        return '{0}-{1}: {2}'.format(positions[0][0], positions[-1][1], ', '.join(adverbs))
    else:
        return 'No adverbs found.'
