def is_abundant(n):
    sum_divisors = 1  # Since 1 is a divisor of every number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            sum_divisors += i
            if i != n // i:  # Add the divisor pair if it's different from the square root
                sum_divisors += n // i
    return sum_divisors > n
```

```python
def is_abundant(n):
    # Calculate the sum of proper divisors of n
    total = 1  # 1 is always a proper divisor
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    # A number is abundant if the sum of its proper divisors is greater than n
    return total > n
```

