def get_coordinates(coord):
    sign_tuple = (0, 0)  # Base sign tuple for checking around the given point
    results = []
    for i in range(4):
        for j in range(4):
            if (i == 0 and j == 0) or (i == 3 and j == 3):
                if (i == 0 and j != 0) or (i != 0 and j == 0):
                    sign_tuple = (i, 1 - j)  # Slightly shifted base around them
                elif (i != 3 and j == 3) or (i == 3 and j != 3):
                    sign_tuple = (i, 1 - j)  # Slightly shifted base around them
            elif i != 0 and j != 0 and i != 3 and j != 3:
                sign_tuple = (i, j)  # Base sign tuple around the point
            if (coord[0] + sign_tuple[0], coord[1] + sign_tuple[1]) == coord:
                results.append([coord[0] + sign_tuple[0], coord[1] + sign_tuple[1]])
    return results
