def max_sum_of_three_consecutive(values, n):
    dp = [0] * n
    dp[0], dp[1], dp[2] = values[0], values[0] + values[1], values[0] + values[1] + values[2]

    for i in range(3, n):
        dp[i] = max(dp[i-2], dp[i-3]) + values[i]

    return max(dp[-1], dp[-2])
```

def max_sum_of_three_consecutive(nums, n):
    prev, curr, next = 0, 0, 0
    if n < 3:
        return 0

    for i in range(n):
        temp = curr
        curr = max(prev + nums[i], curr)   
        prev = temp
        next = curr
    return curr

