  # Iterate through the triangle from the second row
  for level in range(1, len(triangle)):
    # Update the DP dictionary
    for index, value in enumerate(dp):
      if index == 0:
        dp[index] = dp[index] + triangle[level][index]  
      elif index == level:
        dp[index] = dp[index - 1] + triangle[level][index] 
      else:
        dp[index] = min(dp[index], dp[index - 1]) + triangle[level][index] 

  # Return the minimum value from the last level of the DP dictionary 
  return min(dp)
```

