                elif s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    k += 1
                elif s2[j - 1] == s3[k - 1]:
                    dp[i][j] = dp[i][j - 1] + 1
                    k2 += 1
                elif s1[i - 1] == s3[k - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    k += 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    # The longest common subsequence is in the bottom-right corner of the matrix
    return dp[length1][length2]
```

