def lcs_of_three(seq1, seq2, seq3, m, n, p):
    # Create a table to store lengths of common subsequences
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, p + 1):
                if seq1[i - 1] == seq2[j - 1] == seq3[k - 1]:
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1
                else:
                    dp[i][j][k] = max(dp[i][j - 1][k], dp[i - 1][j][k - 1], dp[i - 1][j - 1][k - 1])

    # The length of the longest common subsequence is in dp[m][n][p]
    return dp[m][n][p]
