        for i in range(m+1):
            for j in range(n+1):
                if k == 0 or i == 0 or j == 0:
                    t[k][i][j] = 0
                elif seq3[k-1] == seq1[i-1] == seq2[j-1]:
                    t[k][i][j] = t[k-1][i-1][j-1] + 1
                else:
                    t[k][i][j] = max(t[k-1][i][j], t[k][i-1][j], t[k][i][j-1])

    return t[p][m][n]
