def remove_similar_row(matrix):
    seen = set()
    result = set([(tuple(row), set()) for row in matrix])
    for item,seen_list in result:
        if tuple(item) not in seen:
            seen.add(tuple(item))
            seen_list.add(item)
        else:
            seen_list.add(item)
    unique_rows = [item for item,seen_list in result if len(seen_list) == 1]
    return unique_rows
