def find_Min_Swaps(arr,n):
    swaps = 0
    for i in range(n-1):
        if arr[i] == 0:  # find the index of the first zero
            j = i+1
            while arr[j] == 0 and j<n-1:
                j += 1
            if j<n-1:
                min_pos = j  # find the index of the last zero in this segment
                while min_pos > i:
                    arr[min_pos], arr[min_pos-1] = arr[min_pos-1], arr[min_pos]  # swap the two elements
                    min_pos -= 1
                    swaps += 1
    return swaps
