import heapq

def cheap_items(data, n):
    # Using a min heap to keep track of the n cheapest items
    low = []
    for item in data:
        if len(low) < n:
            heapq.heappush(low, item)
        elif item['price'] < low[0]['price']:
            heapq.heappop(low)
            heapq.heappush(low, item)
    return low
