def min_Swaps(str1, str2):
    n1, n2 = len(str1), len(str2)

    if n1 != n2:
        return -1

    i = j = 0
    swaps = 0

    while i < n1 and j < n2:
        if str1[i] != str2[j]:
            i += 1
            swaps += 1
        else:
            i += 1
            j += 1

    for _ in range(i, n1):
        swaps += 1

    return swaps
```

