import math

def round_up(num, digits):
    # Adjust the fixed point before rounding
    num_str = "{:.{}f}".format(num, digits)

    # Split the string at decimal point
    integer_part, decimal_part = num_str.split('.')

    # Round up the decimal part
    if int(decimal_part[0]) < 5:
        return int(integer_part)
    else:
        return int(integer_part) + 1
```

