def product_Equal(n):
    digit = list()
    count = 0
    product_Odd = 1
    product_Even = 1
    for i in str(n):
        digit.append(int(i))
        count += 1
    if count % 2 == 1:
        product_Odd = product_Odd * digit[0]
    else:
        product_Even = product_Even * digit[0]
    for i in range(1,len(digit)):
        if i % 2 == 0:
            product_Even *= digit[i]
        else:
            product_Odd *= digit[i]
    return product_Even == product_Odd
```

