def product_Equal(n):
    sum1, sum2 = 0, 1
    num = abs(n)
    while num > 0:
        if num % 2 == 0: 
            sum1 += num % 10
        else:
            sum2 *= num % 10
        num //= 10
    return sum1 == sum2
```

