def find_Digits(n):
    if n < 0:
        return 0
    factorial = 1
    digit_count = 0
    for i in range(2, n + 1):
        factorial *= i
        while factorial > 0:
            digit_count += factorial % 10
            factorial //= 10
    return digit_count
```

```python
def find_Digits(n):
    if n == 0:
        return 0
    else:
        product = 1
        while n != 0:
            product = product * n
            n = n - 1
        count = 0
        while product != 0:
            if product % 10 == 0:
                count = count + 1
            product = product // 10
        return count
```

