```python
def min_coins(coins, value, n):
    # Create a list to store the minimum coins required for each value up to the target value
    dp = [float('inf')] * (value + 1)

    # Base case: no coins are needed to make a value of 0
    dp[0] = 0

    # Fill the dp array
    for i in range(1, value + 1):
        for coin in coins:
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[value]
```

```python
def min_coins(coins, value, n):
    m = [[0]*(value+1) for _ in range(n+1)]

    for i in range(n+1):
        for j in range(value+1):
            if i == 0:
                m[i][j] = float('inf')
            elif j == 0:
                m[i][j] = 0
            elif coins[i-1] <= j:
                m[i][j] = min(m[i-1][j], m[i][j-coins[i-1]] + 1)
            else:
                m[i][j] = m[i-1][j]

    return m[n][value]
```

