def min_coins(coins, value, n):
    dp = [0] * (value + 1)
    dp[0] = 0  # base case

    for i in range(1, value + 1):
        min_coins = float('inf')
        for j in range(n):
            if i >= coins[j]:
                min_coins = min(min_coins, 1 + dp[i - coins[j]])
        dp[i] = min_coins

    return dp[value]
```

```python
def min_coins(coins, v, n):
    # base case: if value is 0, no coins needed
    if v == 0:
        return 0

    # base case: if the value cannot be made by any coin, return -1
    if n == 0:
        return -1

    # recursive case
    # if the current coin is applicable for the value, take it
    if coins[n-1] <= v:
        return min(min_coins(coins, v - coins[n-1], n), min_coins(coins, v, n-1)) + 1
    else:
        # if the current coin is not applicable for the value, skip it
        return min_coins(coins, v, n-1)
```

