def min_coins(coins, value, count):
    sizes = len(coins)
    if count == 0: 
        return 0
    if size == 0: 
        return float('inf') # If no coins are available, 
                            # return infinity
    if coins[size - 1] > value:
        return min_coins(coins, value, count - 1)
    else:
        return min(1 + min_coins(coins, value - coins[size - 1], count), 
               min_coins(coins, value, count - 1))
```

