def check_min_heap(arr, index):
    n = len(arr)
    if index >= len(arr) // 2 - 1:
        return True
    left = 2 * index + 1
    right = 2 * index + 2
    if left < n and arr[index] > arr[left]:
        return False
    if right < n and arr[index] > arr[right]:
        return False
    return check_min_heap(arr, left) and check_min_heap(arr, right)
```

