def check_min_heap(arr, index):
    n = len(arr)
    leftChildIndex = 2 * index + 1
    rightChildIndex = 2 * index + 2

    if (leftChildIndex < n and arr[index] > arr[leftChildIndex]):
        return False
    if (rightChildIndex < n and arr[index] > arr[rightChildIndex]):
        return False

    if (leftChildIndex < n):
        if(arr[index] >check_min_heap(arr, leftChildIndex)):
            return False

    if (rightChildIndex < n):
        if(arr[index] >check_min_heap(arr, rightChildIndex)):
            return False

    return True
