def rencontres_number(n, k):
    def factorial(m):
        if m == 0:
            return 1
        result = 1
        for i in range(1, m + 1):
            result *= i
        return result

    C = factorial(n + k) // (factorial(k) * factorial(n))
    return C // (n + 2)
