import math

def count_Divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 2  # i and n/i are divisors, except when i is the square root of n
    if math.sqrt(n) * math.sqrt(n) == n:
        count -= 1  # Correct for double counting if n is a perfect square
    return "Even" if count % 2 == 0 else "Odd"
```

