def rgb_to_hsv(r, g, b):
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    diff = max_color - min_color

    if max_color == 0:
        return (0, 0, 0)

    saturation = (diff / max_color) * 100
    if r == max_color:
        hue = (g - b) / diff if diff != 0 else 0
    elif g == max_color:
        hue = 2 + (b - r) / diff
    else:
        hue = 4 + (r - g) / diff

    hue = hue / 6 * 360
    if hue < 0:
        hue += 360

    return (hue, saturation, max_color * 100 / 255)
