def rgb_to_hsv(r, g, b):
    r_normalized = r / 255.0
    g_normalized = g / 255.0
    b_normalized = b / 255.0

    max_color = max(r_normalized, g_normalized, b_normalized)
    min_color = min(r_normalized, g_normalized, b_normalized)

    delta = max_color - min_color

    if delta == 0:
        return (0, 0, max_color)

    h = (60 * ((g_normalized - b_normalized) / delta) + 360) % 360

    if max_color == r_normalized:
        s = delta / r_normalized
    elif max_color == g_normalized:
        s = delta / g_normalized
    else:
        s = delta / b_normalized

    v = max_color

    return (h, s, v)
