    t = [[float("infinity")] * (n+1) for _ in range(m+1)]
    if cost[0][0] == 0:
        t[0][0] = 0

    # Fill the DP array for the first row and column.
    for j in range(1, n+1):
        t[0][j] = t[0][j-1] + cost[0][j]
    for i in range(1, m+1):
        t[i][0] = t[i-1][0] + cost[i][0]

    # Fill the rest of the DP array.
    for i in range(1, m+1):
        for j in range(1, n+1):
            t[i][j] = cost[i][j] + min(t[i-1][j], t[i][j-1], t[i-1][j-1])

    # The minimum cost to reach (m, n) is stored in t[m][n].
    return t[m][n]
