def modular_sum(arr, n, m):
    # Calculate the sum of the array modulo m
    sum_mod = sum(arr) % m
    # Calculate the target modulo value to check for the subset sum
    target_mod = m // 2

    # Check if the sum modulo m is already zero or m itself
    if sum_mod == 0 or sum_mod == target_mod:
        return True

    # Check all possible subsets
    for i in range(1 << n):
        temp_sum = 0
        for j in range(n):
