def recursive_modular_sum(arr, n, m, dp):
    if n == 0:
        return dp[n][m] = (m == 0)

    if dp[n][m] == -1:
        # Include the current element
        if arr[n-1] <= m:
            include = recursive_modular_sum(arr, n-1, m-arr[n-1], dp)
        else:
            include = False

        # Exclude the current element
        exclude = recursive_modular_sum(arr, n-1, m, dp)

        dp[n][m] = include or exclude

    return dp[n][m]
```

