    if S % m != 0:
        return False

    dp_table = [[False] * (S + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(S + 1):
            if j == 0:
                dp_table[i][j] = True
            else:
                if j < A[i - 1]:
                    dp_table[i][j] = dp_table[i - 1][j]
                else:
                    dp_table[i][j] = dp_table[i - 1][j] or dp_table[i - 1][j - A[i - 1]]

    return dp_table[n][S]
