def modular_sum(nums, n, m):
    # Initialize a 2D list to store results for subproblems
    dp = [[-1 for _ in range(m+1)] for _ in range(n+1)]

    # Base case: sum is 0, count of subsets is 1
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n+1):
        for j in range(m+1):
            if j >= nums[i-1]:
                dp[i][j] = dp[i-1][j] + dp[i-1][j-nums[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Check if there is a subset with sum divisible by m
    return dp[n][m] != 0
```

