def count_Rotation(arr, N):
    low = 0
    high = N - 1
    if arr[low] <= arr[high]:
        return 0
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] > arr[mid + 1]:
            return mid + 1
        elif arr[low] > arr[mid]:
            high = mid - 1
        elif arr[mid] <= arr[high]:
            low = mid + 1
    return -1
