def get_median(sorted_array1, sorted_array2, n):
    if n % 2 == 1:
        return find_single_element(sorted_array1, sorted_array2, n)
    else:
        return (find_single_element(sorted_array1, sorted_array2, n) + find_single_element(sorted_array1, sorted_array2, n + 1)) / 2

def find_single_element(sorted_array1, sorted_array2, n):
    left = 0
    right = 0

    while left < n and right < n:
        if sorted_array1[left] <= sorted_array2[right]:
            if left == right:
                return sorted_array1[left]
            left += 1
        else:
            if left == right:
                return sorted_array2[right]
            right += 1

    if left == n:
        return sorted_array2[right]
    else:
        return sorted_array1[left]
```

