def get_median(arr1, arr2, n):
    i = 0
    j = 0
    odd = n % 2 != 0  # Check if the length of the combined array is odd
    mid = n // 2  # Calculate the middle index
    total = arr1[mid]
    next = arr1[mid + 1] if odd else None  # Check if the left half has an additional element

    while i < n and j < n:
        if arr1[i] < arr2[j]:
            total += arr1[i]
            i += 1
        else:
            total += arr2[j]
            j += 1

        if i == n or j == n:
            break

        if odd:
            total += next  # Add the next element of arr1 (right half) if needed

        if total == 2 * mid:
            return float(total) / 2  # Return the median

    return float(total) / n
