    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            # If both strings have reached the end, the minimum length of supersequence is the length of both strings.
            if i == 0 or j == 0:
                dp[i][j] = i + j
            else:
                # If last characters of both strings are the same, the minimum length of supersequence is the same as the minimum length of the supersequence excluding the last characters.
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    # Otherwise, the minimum length of supersequence is the minimum of the lengths of the supersequence excluding the last character of either string plus 1.
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + 1

    return dp[m][n]
