def min_Swaps(str1, str2):
    if len(str1) != len(str2):
        return -1

    def count_diff(str1, str2):
        diff = 0
        for i in range(len(str1)):
            if str1[i] != str2[i]:
                diff += 1
        return diff

    diff_count = count_diff(str1, str2)

    if diff_count % 2 != 0:
        return -1

    swaps = 0

    for i in range(len(str1)):
        if str1[i] != str2[i]:
            j = i
            while str1[j] != str2[i]:
                j += 1

            # Swap str1[i] and str1[j]
            str1[i], str1[j] = str1[j], str1[i]
            swaps += 1

    return swaps
```

