def max_sum_pair_diff_lessthan_K(arr, K, start):
    if start >= len(arr) - 1:
        return 0
    max_sum = 0
    end = start + 1
    while end < len(arr):
        if arr[start] < arr[end] + K:
            max_sum = max(max_sum, arr[start] + arr[end])
        end += 1
    return max(max_sum, max_sum_pair_diff_lessthan_K(arr, K, start + 1))
