def max_sum_pair_diff_lessthan_K(arr, K, k):
    max_sum = 0
    arr.sort()
    i, j = 0, len(arr) - 1

    while i < j:
        if arr[i] + arr[j] >= K:
            j -= 1
            continue
        if arr[i] + arr[j] + arr[i+1] + arr[j-1] > K:
            j -= 1
        elif arr[i] + arr[j] + arr[i+1] + arr[j-1] - k >= 0:
            max_sum += arr[i] + arr[j]
            i += 1
        else:
            max_sum += arr[i] + arr[j] + arr[i+1] + arr[j-1]
            i += 1
            j -= 1
    return max_sum
```

