def min_coins(coins, value, n):

    # If value is 0, we need 0 coins
    if value == 0:
        return 0

    # Initialize result with a large number
    result = float('inf')

    # Check all possible coin values
    for i in range(n):
        if coins[i] <= value:
            temp = min_coins(coins, value - coins[i], n)
            if temp != float('inf') and temp + 1 < result:
                result = temp + 1

    return result
