def find_First_Missing(arr,n,m):
    for i in range(n):
        # If element is not in the range of 0 to m
        if arr[i] < 0 or arr[i] > m-1:
            arr[i] = 0
    for i in range(m):
        # Find the num to index in arr
        index = abs(arr[i])-1
        if arr[index] > 0:
            arr[index] = -arr[index]
    for i in range(m):
        # The index whose value is positive is the first missing number
        if arr[i] > 0:
            return i+1
    return m+1
