def is_subset(arr1, m, arr2, n):
    # Create a hash table/array to store elements of the second array
    hasharray = [0] * n
    for i in range(n):
        hasharray[i] = 0

    # Mark elements of the second array in hash array
    for i in range(m):
        hasharray[arr2[i] - 1] = 1

    # Check if there is any element of the first array in hash array
    for i in range(m):
        if hasharray[arr1[i] - 1] == 0:
            return False

    return True
