def min_Swaps(s1, s2):
    if len(s1) != len(s2):
        raise ValueError("Both strings must be of the same length")

    misplacements = [(i, j) for i, j in zip(s1, s2) if i != j]
    min_swaps = 0

    for i, _ in enumerate(misplacements):
        for _, j in enumerate(misplacements[i+1:], start=i+1):
            if misplacements[i][j] == misplacements[i][0]:
                misplacements[i] = misplacements[i][1:3] + misplacements[i][0] + misplacements[i][3:] + misplacements[i][2] + [misplacements[i][0]]
