import math

def check_Type_Of_Triangle(a, b, c):
    # Sort the sides to make it easier to check
    sides = sorted([a, b, c])

    # Check if it's a right triangle
    if math.isclose(sides[0]**2 + sides[1]**2, sides[2]**2):
        return "Right-angled Triangle"

    # Check if it's an equilateral triangle
    elif sides[0] == sides[1] == sides[2]:
        return "Equilateral Triangle"

    # Check if it's a scalene triangle
    elif sides[0] != sides[1] != sides[2]:
        return "Scalene Triangle"

    # Check if it's an obtuse triangle
    elif sides[0]**2 + sides[1]**2 < sides[2]**2:
        return "Obtuse-angled Triangle"

    else:
        return "Invalid Triangle"
