def max_sum_increasing_subsequence(arr, n):
    # Initialize the dp array to store the maximum sum of increasing subsequence ending at each position
    dp = [0] * n
    # Base case: The maximum sum of increasing subsequence ending at position 0 is the value itself
    for i in range(0, n):
        dp[i] = arr[i]

    # Build the dp array
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]

    # The maximum sum of increasing subsequence will be in the last element of the dp array
    return dp[n-1]
