def count_Rotation(arr, n):
    start, end = 0, n-1
    while start < end:
        if arr[start] < arr[end]:
            break
        mid = (start + end) // 2
        if arr[mid] >= arr[start]:
            start = mid + 1
        else:
            end = mid
    return start
