def count_Rotation(arr, n):
    if n == 0:
        return 0
    if arr[0] <= arr[n - 1]:
        return 0
    low = 0
    high = n - 1
    res = high
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] > arr[res]:
            res = mid
        if arr[low] <= arr[mid]:
            low = mid + 1
        else:
            high = mid - 1
    return (n - res)
```

