def generate_matrix(n):
    matrix = [[0] * n for _ in range(n)]
    num = 1
    top, bottom, left, right = 0, n-1, 0, n-1

    while top <= bottom and left <= right:
        for i in range(left, right+1):
            matrix[top][i] = num
            num += 1
        top += 1

        for i in range(top, bottom+1):
            matrix[i][right] = num
            num += 1
        right -= 1

        if top <= bottom:
            for i in range(right, left-1, -1):
                matrix[bottom][i] = num
                num += 1
            bottom -= 1

        if left <= right:
            for i in range(bottom, top-1, -1):
                matrix[i][left] = num
                num += 1
            left += 1

    return matrix
```

```python
def generate_matrix(n):
    matrix = [[0]*n for _ in range(n)]
    num = 1

    direction = 0  # 0->right, 1->down, 2->left, 3->up
    row = 0
    col = 0

    while num <= n * n:
        matrix[row][col] = num

        if direction == 0:
            col += 1
            if col == n or matrix[row][col] != 0:
                direction = 1
                row += 1
        elif direction == 1:
            row += 1
            if row == n or matrix[row][col] != 0:
                direction = 2
                col -= 1
        elif direction == 2:
            col -= 1
            if col < 0 or matrix[row][col] != 0:
                direction = 3
                row -= 1
        elif direction == 3:
            row -= 1
            if row < 0 or matrix[row][col] != 0:
                direction = 0
                col += 1

        num += 1

    return matrix
```

