def maximum_product(array):
    max1, max2, max3 = float('-inf'), float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')

    for num in array:
        if num > max1:
            max3, max2, max1 = max2, max1, num
        elif max2 < num < max1:
            max3, max2 = max2, num
        elif num > max3:
            max3 = num

        if num < min1:
            min2, min1 = min1, num
        elif min2 < num < min1:
            min2 = num

    return max(max1 * max2 * max3, max1 * min1 * min2)
