    for lenL in range(2, n + 1):
        for i in range(n - lenL + 1):
            j = i + lenL - 1
            for k in range(i, j):
                if (pairs[k].start <= pairs[i].end and pairs[i].end <= pairs[j].end) or (pairs[k].start <= pairs[j].end and pairs[j].end <= pairs[i].end):
                    matrix[i][j] = max(matrix[i][j], 1 + matrix[i][k] + matrix[k + 1][j])

    return max(matrix[i][j] for i in range(n) for j in range(n))
