def max_chain_length(pairs, n):
    # Initialize a list to store the length of the longest chain that ends at each pair
    dp = [1] * n

    # Sort the pairs based on their starting points
    pairs.sort(key=lambda x: x.begin)

    # Iterate through the sorted pairs
    for i in range(1, n):
        for j in range(i):
            # If the starting point of the current pair is greater than or equal to the ending point of the previous pair
            if pairs[i].begin >= pairs[j].end:
                # Update the length of the longest chain that ends at the current pair
                dp[i] = max(dp[i], dp[j] + 1)

    # Return the maximum value in the dp list, which represents the length of the longest chain
    return max(dp)
```

