import heapq

def nth_super_ugly_number(n, primes):
    ugly_numbers = [1]
    considered = [[prime, index * prime for index in range(n)] for prime in primes]
    heapq.heapify(considered)

    for _ in range(n - 1):
        next_ugly = heapq.heappop(considered).pop()
        if next_ugly not in ugly_numbers:
            ugly_numbers.append(next_ugly)
            for prime in primes:
                if prime * next_ugly not in ugly_numbers:
                    heapq.heappush(considered, [prime * next_ugly, index * prime + 1])
    return ugly_numbers[-1]
