def nth_super_ugly_number(n, primes):
    hash_table = {1: True}
    min_heap = [1]

    for _ in range(n):
        result = heapq.heappop(min_heap)
        if result not in hash_table:
            hash_table[result] = True
            for prime in primes:
                heapq.heappush(min_heap, prime * result)

