def longest_increasing_subsequence(nums):
    if not nums:
        return 0

    n = len(nums)
    # dp[i] means the length of the longest increasing subsequence that ends with nums[i]
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_length = max(dp)
    return max_length
