import heapq

def combine_lists(list1, list2):
    combined_list = []
    heapq.heapify(list1)
    heapq.heapify(list2)

    while list1 and list2:
        if list1[0] <= list2[0]:
            heapq.heappop(list1)
            combined_list.append(list1[0])
        else:
            heapq.heappop(list2)
            combined_list.append(list2[0])

    if list1:
        combined_list.extend(list1)
    elif list2:
        combined_list.extend(list2)

    return combined_list
